42	// Percentages are applied as integer arithmetic (× percent ÷ 100) rather than
43	// as a float rate (× 1.1): this keeps intermediate values integral and avoids
44	// binary floating-point error — 100 * 1.1 is 110.00000000000001, but
45	// (100 * 110) / 100 is exact. Premiums round up in MHPCO's favour at the end.
46	const ONE_HUNDRED_PERCENT = 100;
47	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
48	const ADMIN_FEE = 5;
49	
50	const applyPercent = (amount: number, percent: number): number =>
51	  (amount * percent) / ONE_HUNDRED_PERCENT;
52	
53	const addSurcharge = (amount: number, surchargePercent: number): number =>
54	  applyPercent(amount, ONE_HUNDRED_PERCENT + surchargePercent);
55	
56	const COMPONENT_TYPES = ["rune"];
57	const BUILDING_BLOCK_SIZE = 3;
58	const BUILDING_BLOCK_BASE_PREMIUM = 60;
59	
60	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
61	
62	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
63	
64	// Alike components are grouped into building blocks of 3, which carry a
65	// special base premium; leftovers are priced individually.
66	const componentsBasePremium = (components: Item[]): number => {
67	  const blocks = Math.floor(components.length / BUILDING_BLOCK_SIZE);
68	  const leftovers = components.length % BUILDING_BLOCK_SIZE;
69	  return (
70	    blocks * BUILDING_BLOCK_BASE_PREMIUM +
71	    leftovers * basePremiumOf(components[0])
72	  );
73	};
74	
75	const totalBasePremium = (items: Item[]): number => {
76	  const components = items.filter(isComponent);
77	  const mainItems = items.filter((item) => !isComponent(item));
78	  const mainItemsTotal = mainItems.reduce(
79	    (total, item) => total + basePremiumOf(item),
80	    0,
81	  );
82	  if (components.length === 0) return mainItemsTotal;
83	  return mainItemsTotal + componentsBasePremium(components);
84	};
85	
86	const quote = (step: QuoteStep): QuoteResult => {
87	  const basePremium = totalBasePremium(step.items);
88	  const premiumAfterFirstInsurance = addSurcharge(
89	    basePremium,
90	    FIRST_INSURANCE_SURCHARGE_PERCENT,
91	  );
92	  return { premium: Math.ceil(premiumAfterFirstInsurance) + ADMIN_FEE };
93	};
94	
95	export const runScenario = (scenario: Scenario): ScenarioResult => ({
96	  results: scenario.steps.map(quote),
97	});
