const sumBasePremiums = (items: Item[]): number =>
  items.reduce((total, item) => total + basePremiumOf(item), 0);

// Alike components are grouped into building blocks of 3, which carry a
// special base premium; the remaining components are priced individually.
// Total over the empty group: no components means no blocks and no remainder.
const alikeComponentsBasePremium = (components: Item[]): number => {
  const blockCount = Math.floor(components.length / BUILDING_BLOCK_SIZE);
  const unblocked = components.slice(blockCount * BUILDING_BLOCK_SIZE);
  return blockCount * BUILDING_BLOCK_BASE_PREMIUM + sumBasePremiums(unblocked);
};

const totalBasePremium = (items: Item[]): number => {
  const components = items.filter(isComponent);
  const mainItems = items.filter((item) => !isComponent(item));
  return sumBasePremiums(mainItems) + alikeComponentsBasePremium(components);
};
